-- ===========================================================================
-- rollback_alert_test_data.sql
-- Removes every synthetic merchant injected by inject_alert_test_data.sql
-- and restores APP_METADATA.LAST_DATA_UPDATE.
-- Targeted merchant names (real Indonesian brands, not present in the
-- original dataset):
--   KOPI KENANGAN, JANJI JIWA, MCDONALDS, KFC, CHATIME, J.CO DONUTS, STARBUCKS, FORE COFFEE, XING FU TANG, BAKMI GM
-- ===========================================================================
BEGIN TRANSACTION;

DELETE FROM PROCESSED_CARD_SHARE        WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');
DELETE FROM PROCESSED_CARD_HISTORY      WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');
DELETE FROM PROCESSED_CARD_MONTHLY      WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');
DELETE FROM PROCESSED_MONITORING        WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');
DELETE FROM PROCESSED_MONITORING_WEEKLY WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');
DELETE FROM TARGET                      WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');
DELETE FROM WEEKLY_MONITOR              WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');

UPDATE APP_METADATA SET value='2026-04-07 16:32:54' WHERE key='LAST_DATA_UPDATE';
DELETE FROM APP_METADATA WHERE key='NEW_DATA_SIGNAL';

SELECT 'PROCESSED_CARD_SHARE'        AS tbl, COUNT(*) AS n FROM PROCESSED_CARD_SHARE        WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM')
UNION ALL SELECT 'PROCESSED_CARD_HISTORY',      COUNT(*) FROM PROCESSED_CARD_HISTORY      WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM')
UNION ALL SELECT 'PROCESSED_CARD_MONTHLY',      COUNT(*) FROM PROCESSED_CARD_MONTHLY      WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM')
UNION ALL SELECT 'PROCESSED_MONITORING',        COUNT(*) FROM PROCESSED_MONITORING        WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM')
UNION ALL SELECT 'PROCESSED_MONITORING_WEEKLY', COUNT(*) FROM PROCESSED_MONITORING_WEEKLY WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM')
UNION ALL SELECT 'TARGET',                      COUNT(*) FROM TARGET                      WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM')
UNION ALL SELECT 'WEEKLY_MONITOR',              COUNT(*) FROM WEEKLY_MONITOR              WHERE MERCHANT_GROUP IN ('KOPI KENANGAN','JANJI JIWA','MCDONALDS','KFC','CHATIME','J.CO DONUTS','STARBUCKS','FORE COFFEE','XING FU TANG','BAKMI GM');

COMMIT;
